from hermes_tools import terminal
g=[[0]*12 for _ in range(11)]
source={1:[6],2:[5,6,7],3:[7],4:[6,7,8],5:[6,7]}
for r,cs in source.items():
 for c in cs:g[r][c]=4
# mirror across vertical axis halfway after rightmost source column c=8; clip at grid boundary
for r,cs in source.items():
 for c in cs:
  cc=17-c
  if cc<12:g[r][cc]=4
assert len(g)==11 and all(len(row)==12 for row in g)
assert all(6 not in row for row in g)
print('\n'.join(' '.join(map(str,row)) for row in g))

from hermes_tools import terminal
grid=[[0]*12 for _ in range(11)]
shape={1:[6],2:[5,6,7],3:[7],4:[6,7,8],5:[6,7]}
for r,cs in shape.items():
 for c in cs:grid[r][c]=4
# mirror toward upper-pointing 6, across boundary above row 1; only reflected row 0 remains in canvas
for r,cs in shape.items():
 rr=1-r
 if 0<=rr<11:
  for c in cs:grid[rr][c]=4
assert len(grid)==11 and all(len(row)==12 for row in grid)
print('\n'.join(' '.join(map(str,row)) for row in grid))
